    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv14a411c7ze', 'course-bili-bv14a411c7ze', '100001', '0', 'BILI-AI-009', 'course-category-ai', 'instructor-bili-1759890150', '【计算机视觉实战项目】基于Python与OpenCV实现的图像处理全套解析！从基础原理到代码实战，全程通俗易懂，适合所有零基础入门学习！-ML/DL/CV', '73 讲完整课程 · 9 小时 34 分钟', 'OpenCV（Open Source Computer Vision Library）是一个开源的计算机视觉库，支持多种编程语言（如C++、Python）。它提供丰富的图像处理功能，包括： 基础操作 ：读取/保存图像、色', '课程简介：OpenCV（Open Source Computer Vision Library）是一个开源的计算机视觉库，支持多种编程语言（如C++、Python）。它提供丰富的图像处理功能，包括： 基础操作 ：读取/保存图像、色彩空间转换（RGB↔灰度）、裁剪/缩放 图像增强 ：滤波（高斯/中值）、边缘检测（Canny/Sobel）、直方图均衡化 特征分析 ：角点检测（Harris/SIFT）、轮廓查找、模板匹配 高级应用 ：人脸识别、目标跟踪、AR增强现实 广泛应用于工业检测、医学影像、自动驾驶等领域，以高效算法和跨平台特性著称。课程结构：共 10 章 73 讲，累计时长 9 小时 34 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/cc8a2b58fcb0325c9be8eb4923a92ff9f759edff.jpg', '["人工智能","机器学习","大模型","计算机视觉实战项目","全程通俗易懂","适合所有零基础入门学习！"]', 34493, 73, 314142, '4.5', 76077, 'BV14A411C7ZE', '79.00', '126.40', 'CNY', 0, 0, 'standard', NULL, '唐宇迪的AI入门课', 0, 'tenant', 'published', '2023-01-29T08:47:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
